import openpyxl
wb = openpyxl.load_workbook('app_strings_translations.xlsx')
ws = wb.active
header = [c.value for c in ws[1]]
status_col = header.index('status') + 1
en_col = header.index('english') + 1

langs = [
    (header.index('hindi') + 1, 0),
    (header.index('kannada') + 1, 1),
    (header.index('malayalam') + 1, 2),
    (header.index('tamil') + 1, 3),
    (header.index('telugu') + 1, 4),
]

patched = 0
for i, row in enumerate(ws.iter_rows(min_row=2), start=2):
    if ws.cell(row=i, column=status_col).value == 'Pending':
        en = ws.cell(row=i, column=en_col).value
        if en in translations:
            t = translations[en]
            for col_idx, t_idx in langs:
                ws.cell(row=i, column=col_idx).value = t[t_idx]
            ws.cell(row=i, column=status_col).value = 'Done'
            patched += 1

wb.save('app_strings_translations.xlsx')
print(f"Patched {patched} strings in Excel.")
